import {tr} from './i18n';
import {useEffect,useId,useRef,useState} from 'react';
import {ArrowLeft,ArrowRight,BookOpen,Check,CheckCircle2,ChevronRight,Compass,HelpCircle,Lightbulb,Search,ShieldCheck,X} from 'lucide-react';

type Lesson={id:string;title:string;duration:string;intro:string;steps:[string,string][];result:string;tip:string;page:string;action:string};
const lessons:Lesson[]=[
  {id:'academy-horizon',title:'Projeter l’académie sur plusieurs saisons',duration:'3 min',intro:'Dans Entraînement, comparez les jeunes et leurs cibles sur un horizon de une à quatre saisons.',steps:[
    ['Choisir le jeune et son horizon','Filtrez par génération indicative et comparez les étoiles cumulées. Vérifiez la saison et la semaine de départ ; la semaine courante est exclue par défaut, car son entraînement peut déjà être compris dans l’observation.'],
    ['Préparer les séances','Le programme de chaque saison alimente la projection. Le gain par défaut est de 0,20 par compétence et séance, plafonné à 13,99. Un 14 déjà observé reste conservé ; les gains en match et les promotions ne sont pas simulés.'],
    ['Comparer les cibles','Renseignez vos cibles par compétence. Les objectifs enregistrés sont rappelés ; les cibles saisies ici servent à la comparaison et restent locales à cette vue. Enregistrez les modifications du programme avant de quitter la page.']
  ],result:'Vous voyez les séances manquantes et les compétences projetées saison par saison.',tip:'Les compétences masquées restent inconnues. La projection suppose que le jeune reste à l’académie sur l’horizon choisi ; la génération affichée ne garantit pas une sélection U20.',page:'training',action:'Projeter ma formation'},
  {id:'national',title:'Suivre une sélection U20 ou nationale',duration:'2 min',intro:'Une sélection dispose de son propre espace, séparé des clubs, des notes et de leur historique.',steps:[
    ['Rattacher la sélection','Dans Connexion & données, importez votre compte Classic, puis choisissez le pays et le type de sélection. Classic doit confirmer que ce compte est le sélectionneur actuel.'],
    ['Préparer et comparer','Choisissez la sélection en haut de page pour consulter l’effectif, préparer un XV local, analyser les matchs et suivre les observations. Les clubs gardent la gestion des entraînements et de leurs finances.'],
    ['Actualiser ou suspendre','Actualisez l’effectif régulièrement. Si votre mandat se termine, suspendez sa synchronisation depuis Connexion & données ; vos observations et notes restent conservées.']
  ],result:'Votre sélection apparaît parmi vos équipes sans mélanger ses données avec celles d’un club.',tip:'Cette connexion lit les données et prépare votre travail dans BRT. Elle ne publie pas de composition nationale dans Classic.',page:'settings',action:'Gérer mes sélections'},
  {id:'coach',title:'Lire les conseils du coach',duration:'2 min',intro:'Optimisation et Mode vacances donnent une lecture des points forts, des besoins et des profils observés.',steps:[
    ['Vérifier la couverture','Une compétence inconnue ne compte jamais comme zéro. Les comparaisons collectives demandent suffisamment de joueurs et de compétences observés.'],
    ['Lire le profil individuel','Le conseil indique une affinité de poste et une compétence à travailler. Confirmez la forme, l’énergie et les blessures avant de décider ; l’âge et le CSR ne suffisent pas à conclure.'],
    ['Planifier la prochaine observation','Selon le retour de Franck, l’entraînement senior a lieu le mardi à 12 h et celui des jeunes le jeudi à 12 h, heure locale du jeu. Confirmez l’horaire dans Classic et actualisez après la séance pour mesurer l’évolution.']
  ],result:'Vous préparez des priorités fondées sur les compétences réellement connues.',tip:'Ces conseils sont indicatifs. Un joueur peut encore progresser après 29 ans ; suivez les évolutions individuelles plutôt qu’un seuil d’âge automatique.',page:'optimization',action:'Lire les conseils'},
  {id:'registration',title:'Créer son compte BRT',duration:'1 min',intro:'Chaque manager crée son espace privé depuis la page de connexion.',steps:[
    ['Créer mon compte','Choisissez un identifiant, une adresse e-mail et un mot de passe de 12 caractères minimum. L’avatar est facultatif : maillot, bouclier, trophée ou ballon.'],
    ['Retrouver ses clubs','Après l’inscription, importez votre compte Classic avec sa clé manager. Vous pouvez aussi ajouter votre club par son identifiant puis importer un fichier de joueurs.'],
    ['Personnaliser son espace','Votre avatar et vos préférences restent modifiables dans Profil & affichage. Votre adresse reste privée ; elle n’est pas vérifiée et ne permet pas une réinitialisation automatique du mot de passe.']
  ],result:'Votre espace est ouvert et prêt à accueillir vos données.',tip:'Un compte BRT est nécessaire pour utiliser l’atelier. Il est distinct de votre compte dans le jeu.',page:'profile',action:'Voir mon profil'},
  {id:'starter',title:'Bien démarrer son club',duration:'3 min',intro:'Les conseils de démarrage de Franck du 31 octobre 2026 aident à préparer les premières décisions. Adaptez-les à votre club : ce ne sont pas des règles officielles de Classic.',steps:[
    ['Choisir librement son mentor','Cherchez un mentor disponible dans Classic pour vous accompagner et poser vos premières questions. Le choix vous appartient ; aucun manager n’est imposé par BRT.'],
    ['Préserver la dotation de départ','Les 300 000 unités de monnaie virtuelle évoquées correspondent à une dotation de départ, jamais à une estimation de votre solde actuel. Relisez la trésorerie réelle du club et gardez une réserve avant de dépenser.'],
    ['Différer les achats de joueurs','Au départ, prenez le temps de découvrir votre effectif et vos besoins avant d’acheter des joueurs. Ce conseil laisse la trésorerie disponible pour les premières priorités du club.'],
    ['Limiter le staff au départ','Franck conseille le recruteur de l’académie et le manager, sans adjoints au début. Vérifiez les postes déjà occupés et leur coût dans Classic avant tout recrutement.'],
    ['Préparer le stade','Dans Stade & finances, choisissez une capacité totale et utilisez « Remplacer les cinq capacités cibles » pour reprendre les proportions existantes 22 / 39 / 30 / 8 / 1 %. Renseignez ensuite les coûts du devis réel et la réserve. Enregistrer un scénario ne lance aucune construction.'],
    ['Vérifier l’échéance économique','Le repère communiqué est mardi à minuit. Confirmez la date et le fuseau horaire dans le calendrier du jeu avant de créer un rappel. BRT n’en déduit aucune échéance datée.'],
    ['Préparer ensuite l’équipe type','Une fois ces priorités relues, actualisez l’effectif et préparez votre XV dans Effectif & XV ou Optimisation. Relisez les joueurs disponibles avant de l’appliquer dans Classic.']
  ],result:'La carte « Bien démarrer » de l’accueil permet de suivre ces sept repères pour chaque club.',tip:'Les cases « Pris en compte » sont vos déclarations privées. Les cocher ne réalise aucune action dans Classic et ne prouve pas qu’une opération a été effectuée.',page:'home',action:'Retrouver « Bien démarrer »'},
  {id:'contact',title:'Signaler un bug ou proposer une idée',duration:'1 min',intro:'Contact & idées relie les managers à Pierig, administrateur de l’outil.',steps:[
    ['Choisir le type de retour','Sélectionnez bug, amélioration ou nouveauté. Donnez un sujet clair, les étapes pour reproduire le problème ou le bénéfice attendu.'],
    ['Envoyer les informations utiles','Indiquez votre e-mail de réponse et confirmez le partage avec Pierig. Ne transmettez aucun mot de passe ni clé API. Vos données de club ne sont pas jointes.'],
    ['Suivre la demande','Après connexion, Contact & idées affiche vos demandes et leur statut : reçu, en cours de lecture, prévu ou traité.']
  ],result:'Le message est enregistré dans la boîte administrateur et une notification e-mail est tentée si les notifications sont configurées.',tip:'La confirmation garantit l’enregistrement du message dans votre historique privé, même si la notification e-mail échoue.',page:'contact',action:'Contacter Pierig'},
  {id:'profile',title:'Faire de l’atelier votre espace',duration:'2 min',intro:'Votre profil et vos préférences d’affichage sont sauvegardés dans votre espace privé, sur tous vos appareils.',steps:[
    ['Personnaliser le profil','Ouvrez Profil & affichage. Choisissez votre nom affiché, vos initiales, votre numéro et éventuellement un club de rugby favori. Votre identifiant de connexion reste inchangé.'],
    ['Choisir vos repères','Réglez la taille du texte, la densité, les mouvements, la bannière et la page qui s’ouvre à la prochaine connexion. Activez les rubriques utiles du tableau de bord et déplacez-les avec les flèches.'],
    ['Enregistrer puis retrouver','Enregistrez le profil pour appliquer vos choix. Les couleurs et le blason du club sélectionné se règlent plus bas. En cas de modification dans une autre session, comparez les versions avant de sauvegarder.']
  ],result:'Le tableau de bord reflète vos habitudes et reste accessible.',tip:'Le réglage de mouvements réduits du système est toujours respecté. Choisir un club favori ne lie pas ce club à votre compte Classic.',page:'profile',action:'Personnaliser mon espace'},
  {id:'progression',title:'Lire la progression dans le temps',duration:'3 min',intro:'Les courbes montrent les observations réellement conservées, avec leurs dates et leurs sources.',steps:[
    ['Choisir ce que vous observez','Dans Progression, choisissez seniors ou académie, le collectif ou un joueur, une compétence ou le CSR, puis la période.'],
    ['Lire les points et les écarts','Un point correspond à une observation. Une compétence jusque-là masquée est un dévoilement, pas un gain. Un changement d’effectif ou de joueurs renseignés rend les moyennes moins comparables.'],
    ['Vérifier les détails','Consultez le tableau associé à la courbe pour retrouver les valeurs, leurs sources et leur comparabilité. Actualisez régulièrement les données pour constituer votre historique.']
  ],result:'Vous distinguez une variation mesurée d’une donnée simplement nouvelle.',tip:'Une seule observation ne suffit pas à mesurer un progrès. Une courbe n’établit ni la cause d’une variation ni une prévision.',page:'progression',action:'Explorer la progression'},
  {id:'daily',title:'Organiser sa journée de manager',duration:'2 min',intro:'Le suivi quotidien rassemble les priorités de vos clubs et vous aide à choisir la prochaine action utile.',steps:[
    ['Lire les priorités','Sur le tableau de bord, consultez les échéances, la fraîcheur des effectifs, les joueurs suivis et les incidents du mode vacances. La date des observations compte autant que leur contenu.'],
    ['Choisir ses alertes','Réglez les catégories qui vous intéressent. Les alertes restent dans votre espace privé. Les notifications du navigateur nécessitent votre accord et ne fonctionnent que lorsque l’application est ouverte.'],
    ['Passer à l’action','Choisissez le club indiqué avant de préparer sa composition ou son programme. Un rappel du calendrier n’envoie aucun ordre dans Classic.']
  ],result:'Vous disposez d’une liste de priorités pour vos clubs.',tip:'Aucune alerte de l’outil ne remplace la connexion régulière au jeu. Les données ne sont fraîches qu’après une actualisation réussie.',page:'home',action:'Voir mes priorités'},
  {id:'season',title:'Préparer le calendrier de la saison',duration:'2 min',intro:'Réunissez les matchs, séances et rappels dans un calendrier privé, avec vos priorités et votre rotation prévue.',steps:[
    ['Ajouter les rencontres','Dans Saison & calendrier, importez les prochaines rencontres disponibles dans Classic ou ajoutez un événement manuel. Vérifiez sa date et son fuseau horaire.'],
    ['Définir le contexte','Indiquez l’importance, vos notes et les joueurs que vous prévoyez de faire tourner. Ajoutez vos séances et rappels pour préparer les semaines suivantes.'],
    ['Enregistrer et reprendre','Enregistrez la date et attendez la confirmation. Une saisie modifiée demande confirmation avant abandon. Si un autre onglet a changé le calendrier, votre saisie reste affichée : relevez les éléments à garder avant de recharger explicitement la version enregistrée.']
  ],result:'Votre calendrier relie les échéances et les choix à préparer.',tip:'Les entraînements du calendrier sont des événements de préparation. Le programme de l’académie reste dans Entraînement et son application reste à faire dans Classic.',page:'season',action:'Ouvrir le calendrier'},
  {id:'lineup-lab',title:'Comparer des compositions et couvrir le banc',duration:'3 min',intro:'Le laboratoire de composition conserve vos choix et vous aide à comparer plusieurs équipes.',steps:[
    ['Fixer vos contraintes','Choisissez l’échelle d’énergie, les exclusions et les titulaires ou postes à conserver. Un joueur indisponible ne devient pas disponible parce qu’il est verrouillé.'],
    ['Examiner le terrain et les réserves','Calculez la proposition, sélectionnez les postes sur le terrain et lisez les indications de couverture du banc. Une lacune reste visible plutôt que d’être masquée par un score.'],
    ['Conserver plusieurs choix','Nommez vos scénarios et comparez leurs effectifs et indices. Relisez les observations utilisées avant de retenir une composition pour un match.']
  ],result:'Vous pouvez comparer une équipe type et une rotation sans perdre vos contraintes.',tip:'Les scores sont des indices propres à l’outil, pas des probabilités de victoire. Sauvegarder un scénario ne l’envoie pas au jeu.',page:'optimization',action:'Ouvrir le laboratoire'},
  {id:'academy-followup',title:'Suivre les objectifs des jeunes',duration:'2 min',intro:'Reliez les objectifs individuels, les générations et les observations successives de votre académie.',steps:[
    ['Choisir un objectif','Dans le suivi de l’académie, choisissez le jeune et la compétence à travailler. Les listes par génération reprennent la projection personnelle de Franck.'],
    ['Lire les changements','Distinguez une valeur numérique qui augmente d’une compétence qui vient simplement d’être dévoilée. Les dates et les sources restent visibles.'],
    ['Rapprocher les séances','Ouvrez « Séances planifiées et réalisées », puis choisissez « Déclarer la séance » sur un créneau renseigné. La saison, la semaine, le créneau et la compétence sont repris du planning. Renseignez la date réelle, laissée vide, vérifiez la compétence réalisée puis enregistrez. Une déclaration reste manuelle.']
  ],result:'Vous suivez des objectifs et des changements observés, avec leur provenance.',tip:'Une progression constatée après un entraînement ne prouve pas, à elle seule, que cette séance en est la cause.',page:'academy',action:'Suivre mon académie'},
  {id:'opponents',title:'Construire un dossier adversaire',duration:'2 min',intro:'Regroupez plusieurs rencontres pour lire les habitudes d’un adversaire avec des données comparables.',steps:[
    ['Rattacher les matchs','Dans Analyse des matchs, associez chaque rencontre importée au bon club, au côté observé et à l’adversaire. Le type Club/U20/NT fait partie de l’identité du match.'],
    ['Filtrer le dossier','Choisissez l’adversaire et la saison. Vérifiez le nombre de rencontres et le nombre d’événements réellement classés.'],
    ['Lire la matrice par zone','La matrice croise quatre zones relatives à l’adversaire et cinq types d’attaque. Chaque cellule donne un nombre d’actions et leur pourcentage parmi les actions adverses classées de cette zone. La dernière colonne donne ce dénominateur ; une zone sans observation affiche un tiret, sans pourcentage.']
  ],result:'Vous disposez d’un dossier regroupant des rencontres explicitement rattachées.',tip:'La couverture porte sur tous les événements des matchs retenus, des deux côtés. Les pourcentages de la matrice portent sur les seules actions adverses classées de chaque zone. Ces observations ne prédisent pas la prochaine tactique.',page:'matches',action:'Préparer un adversaire'},
  {id:'club-style',title:'Personnaliser le club et partager un retour',duration:'1 min',intro:'Chaque club peut avoir son identité visuelle, et chaque écran peut faire l’objet d’un retour précis.',steps:[
    ['Choisir son identité','Dans Profil & affichage, choisissez une palette et les éléments du blason. Votre personnalisation concerne l’outil, pas le site Classic.'],
    ['Décrire un retour','Ouvrez le bouton de retour de l’écran concerné. Expliquez le résultat attendu et ce que vous avez observé, sans coller de clé API ni de mot de passe.'],
    ['Choisir le destinataire','Un retour privé reste dans votre espace. Un retour destiné à l’administrateur lui transmet le texte et le contexte indiqués ; il peut ensuite être suivi par son statut.']
  ],result:'Votre club a ses repères visuels et vos retours sont conservés au bon endroit.',tip:'Un problème d’accès ou de données se comprend mieux avec le club, l’écran et les étapes suivies. Aucun secret n’est nécessaire.',page:'profile',action:'Personnaliser mon club'},
  {id:'start',title:'Prendre ses repères',duration:'1 min',intro:'L’atelier vous aide à observer et à préparer vos décisions. Les envois de compositions se contrôlent dans Mode vacances ; les autres préparations restent dans l’outil.',steps:[
    ['Deux accès différents','Connectez-vous ici avec l’identifiant et le mot de passe de l’outil choisis lors de l’inscription ou reçus sur invitation. Votre compte et votre mot de passe Classic restent distincts.'],
    ['Un espace par manager','Vos clubs, notes, favoris, compositions et plannings sont privés. Le menu à gauche ouvre les rubriques ; sur téléphone, utilisez le bouton de menu en haut à gauche.'],
    ['Lire, préparer, puis jouer','L’import lit Classic. Les notes, le XV et le planning se sauvegardent dans cet outil. Mode vacances permet un envoi de composition après confirmation, ou selon des règles datées explicitement activées. Les séances d’entraînement restent à configurer dans le jeu.']
  ],result:'Vous savez où vous connecter et ce que l’outil peut faire pour vous.',tip:'Enregistrez vos notes, XV, planning et dates avant de partir. Un brouillon modifié demande confirmation avant de changer de rubrique, de club ou de vous déconnecter. Refusez l’abandon pour continuer la saisie ; ce rappel ne remplace pas l’enregistrement.',page:'home',action:'Ouvrir le tableau de bord'},
  {id:'connect',title:'Importer son compte Classic',duration:'2 min',intro:'Une seule clé manager permet de retrouver toutes les équipes rattachées à votre compte, leurs joueurs, académies et données de club.',steps:[
    ['Retrouver la bonne clé','Dans Classic, ouvrez Moi → Mon compte → Blackout Rugby API (en anglais : Me → Account). Copiez toute la ligne Access Key : m=…&mk=… . Il s’agit d’une clé d’accès, pas de votre mot de passe.'],
    ['Relier le compte','Dans Connexion & données, collez cette ligne dans « Clé d’accès de votre manager Classic », puis cliquez sur « Importer mon compte et mes équipes ». Au premier accès sans club, ce formulaire est déjà affiché. Laissez la lecture se terminer.'],
    ['Vérifier puis actualiser','Le nom du manager et ses équipes apparaissent lorsque l’import a réussi. Plus tard, « Actualiser toutes mes équipes » relit leurs données. Si votre compte est déjà relié, commencez directement par ce bouton.']
  ],result:'Votre compte est indiqué comme connecté et vos clubs apparaissent dans le sélecteur.',tip:'Gardez cette clé privée. Si des champs développeur apparaissent, demandez à l’administrateur de configurer l’accès de l’outil. « Reconnecter mon compte » permet de saisir une nouvelle clé manager.',page:'settings',action:'Ouvrir Connexion & données'},
  {id:'clubs',title:'Choisir son club et lire les données',duration:'1 min',intro:'Le club sélectionné donne le contexte de votre travail. Prenez ce réflexe avant de préparer une équipe.',steps:[
    ['Choisir le club','Utilisez la liste « Choisir un club » en haut à droite. L’académie, l’effectif, le planning, le XV et le stade se chargent pour ce club. Vos matchs importés restent dans la bibliothèque de votre espace manager.'],
    ['Regarder la source et sa date','La date d’observation sous les tableaux indique quand les données ont été relevées. Un instantané est une photo de l’effectif à un moment donné ; il ne s’actualise pas tout seul.'],
    ['Distinguer ses équipes et les clubs suivis','Le bloc du compte Classic liste vos équipes rattachées. La rubrique « Les clubs suivis » peut aussi contenir un club ajouté à la main ou issu du classeur. L’ajout d’un club ne donne pas de droits sur ses données privées.']
  ],result:'Vous travaillez sur le bon club et vous connaissez la fraîcheur des données.',tip:'Deux imports identiques n’ajoutent pas de doublon. Pour observer une évolution, il faut une nouvelle observation avec des données différentes.',page:'home',action:'Retrouver mon tableau de bord'},
  {id:'academy',title:'Observer et comparer les joueurs',duration:'2 min',intro:'L’académie sert à repérer les jeunes à suivre. Les mêmes outils de recherche et de comparaison existent pour les seniors.',steps:[
    ['Trouver un profil','Recherchez un nom ou une partie de l’identifiant du joueur, sans vous soucier des accents, de la casse ou des espaces répétés. Les filtres affinent la liste. Cliquez sur un titre de colonne pour trier : les compétences numériques suivent leur valeur et les compétences inconnues restent à la fin dans les deux sens.'],
    ['Ouvrir une fiche et garder une trace','Cliquez sur le nom du joueur, rédigez votre note puis choisissez « Enregistrer la note ». Attendez la confirmation dans la fiche ; une erreur y reste visible avec votre texte. En cas de conflit, « Relire la note enregistrée » remplace le brouillon après confirmation. L’étoile du tableau met à jour le suivi et signale aussi une modification concurrente.'],
    ['Comparer puis mesurer les progrès','Cochez jusqu’à trois cases dans la colonne COMPARER : les profils apparaissent sous le tableau. Après une nouvelle synchronisation, la fiche et l’historique permettent de retrouver les changements observés.']
  ],result:'Vous avez repéré un joueur, conservé une note et comparé plusieurs profils.',tip:'? signifie non dévoilé ; B, M et H indiquent un niveau bas, moyen ou haut. Une compétence inconnue n’est jamais transformée en zéro. La projection U20 et les affinités sont des aides, pas des verdicts officiels.',page:'academy',action:'Explorer mon académie'},
  {id:'squad',title:'Préparer son XV',duration:'2 min',intro:'Construisez une composition pour le club sélectionné et conservez-la pour préparer votre prochaine rencontre.',steps:[
    ['Consulter les seniors','Dans Effectif & XV, recherchez et comparez les joueurs. Les fiches aident à examiner les compétences, la taille, le poids, l’énergie et les affinités de poste.'],
    ['Répartir les joueurs','Ouvrez l’onglet « Composer mon XV ». Choisissez les titulaires aux postes 1 à 15 et, si besoin, les remplaçants 16 à 23. Un joueur déjà choisi ne peut pas occuper un second poste.'],
    ['Sauvegarder la composition','Cliquez sur « Enregistrer le XV » et attendez la confirmation ; les choix sont bloqués pendant la sauvegarde. Si un autre onglet a modifié le XV, votre brouillon reste affiché. Relevez vos choix avant de recharger explicitement la composition enregistrée, puis reprenez vos changements.']
  ],result:'Votre composition est sauvegardée pour ce club dans l’atelier.',tip:'Changer d’onglet, de rubrique ou de club avec des choix non enregistrés demande confirmation. Pour envoyer le XV dans Classic, ouvrez Mode vacances et vérifiez son aperçu, ou reportez vous-même la composition dans le jeu.',page:'squad',action:'Ouvrir Effectif & XV'},
  {id:'training',title:'Planifier l’entraînement',duration:'2 min',intro:'Le planning sert à organiser une saison de seize semaines, avec quatre créneaux par semaine.',steps:[
    ['Choisir la saison','Ouvrez Entraînement, vérifiez le club puis renseignez la saison. Les colonnes S1 à S16 sont les semaines ; les lignes T1 à T4 sont les quatre créneaux.'],
    ['Construire le programme','Choisissez une compétence dans chaque case souhaitée. La légende développe les abréviations. Les barres sous la grille résument la répartition des 64 créneaux possibles.'],
    ['Enregistrer et traiter un conflit','Cliquez sur « Enregistrer » et attendez « Enregistré » ; la grille et la saison sont bloquées pendant la sauvegarde. Un changement dans un autre onglet empêche l’écrasement et conserve votre brouillon. Relevez vos choix avant de recharger explicitement le planning enregistré pour les reprendre.']
  ],result:'Votre programme est conservé pour le club et la saison choisis.',tip:'Changer de saison, de club ou de rubrique avec un brouillon demande confirmation. Configurez les séances dans Classic, puis déclarez celles réellement effectuées dans le suivi de l’académie. Le dernier export ne constitue pas un historique des séances.',page:'training',action:'Ouvrir mon planning'},
  {id:'matches',title:'Comprendre l’analyse d’un match',duration:'2 min',intro:'Comparez les choix d’attaque des deux équipes, en gardant à l’esprit la part des événements réellement classés.',steps:[
    ['Importer la rencontre','Dans Analyse des matchs, renseignez l’ID de la rencontre Classic et son type : Club, U20 ou Sélection nationale. Cliquez sur « Analyser », puis sélectionnez la carte du match. Les identifiants des équipes et des joueurs ne sont pas des IDs de match.'],
    ['Changer de point de vue','Dans l’analyse, choisissez le nom de l’équipe à étudier. Les zones vont de « Nos 22 m » à « Leurs 22 m » ; le tableau répartit percussion, pick and go, large, créatif et jeu au pied.'],
    ['Lire la couverture et les sources','Vérifiez les nombres d’actions classées, estimées et non classées. Ouvrez « Voir les événements sources » pour relire les commentaires. Les pourcentages portent uniquement sur les actions classées.']
  ],result:'Vous savez lire les zones, comparer les équipes et juger la portée des chiffres.',tip:'La reconnaissance des commentaires est estimative. Une faible couverture ne permet pas de conclure sur l’ensemble du match. Les événements déjà classés peuvent aussi être importés dans le format indiqué par la fenêtre d’import.',page:'matches',action:'Ouvrir l’analyse des matchs'},
  {id:'optimization',title:'Optimiser ses équipes et sa saison',duration:'3 min',intro:'L’espace Optimisation transforme les données importées en propositions expliquées. Vous gardez le dernier mot sur la composition, le programme et la stratégie.',steps:[
    ['Choisir le contexte','Ouvrez Optimisation et choisissez un objectif : performance, récupération ou développement. Réglez le seuil d’énergie et la saison. Le périmètre permet de comparer le club courant ou tous les clubs présents dans votre espace privé. Vérifiez les dates des observations et les avertissements.'],
    ['Examiner les propositions','Consultez les priorités, leurs chiffres et les données manquantes. Le XV répartit les joueurs sans doublons selon les affinités connues ; les blessures connues et le seuil d’énergie limitent les candidats. Le programme de l’académie propose des compétences à travailler seulement lorsqu’elles sont dévoilées et conserve les créneaux déjà remplis.'],
    ['Prévisualiser, puis enregistrer','Examinez le XV ou le programme avant de confirmer sa sauvegarde pour le club actuellement sélectionné. La composition sauvegardée peut être remplacée ; le programme proposé complète uniquement les cases libres à partir de la semaine retenue. Changez de club dans le sélecteur principal pour enregistrer une proposition d’un autre club. Pour envoyer le XV, ouvrez Mode vacances et vérifiez son aperçu. Configurez les séances dans Classic vous-même.'],
    ['Préparer les rencontres','L’onglet Matchs utilise la bibliothèque de votre espace : une rencontre importée n’est pas forcément celle du club sélectionné. Lisez les observations des deux équipes, la couverture et les effectifs d’actions classées. Un petit échantillon donne des pistes à vérifier, pas une tactique gagnante garantie.']
  ],result:'Vous avez comparé des options et conservé les propositions utiles en comprenant leurs limites.',tip:'Un score d’affinité est un indice de préparation, pas une probabilité de victoire. Les compétences, blessures ou énergies inconnues sont signalées. Actualisez les données avant une décision ; les conseils de saison ne remplacent pas le vrai calendrier du jeu.',page:'optimization',action:'Ouvrir Optimisation'},
  {id:'stadium',title:'Comparer les projets du stade',duration:'2 min',intro:'Comparez une capacité cible et plusieurs projets chiffrés, en conservant une réserve de trésorerie.',steps:[
    ['Partir de données récentes','Dans Stade & finances, cliquez sur « Actualiser le club » pour relire ses données. Vérifiez le nombre de membres et les capacités actuelles.'],
    ['Comparer les hypothèses','Ajustez les membres, le multiplicateur et les capacités pour une simulation. La cible est répartie entre les cinq types de places ; la colonne « À ajouter » montre les sections déficitaires.'],
    ['Préparer les cinq cibles d’un scénario','Saisissez une capacité totale dans « Répartir une capacité totale », relisez l’aperçu puis cliquez sur « Remplacer les cinq capacités cibles ». Seules les cibles du brouillon sont remplacées. La répartition en places entières conserve exactement le total saisi.'],
    ['Chiffrer et conserver les projets','Renseignez les capacités actuelles, les coûts unitaires du devis réel, la trésorerie et la réserve à conserver, en monnaie virtuelle. Donnez un nom à chaque projet puis enregistrez pour comparer le coût et le reste disponible. Une donnée manquante reste inconnue.']
  ],result:'Vous comparez des projets enregistrés sans modifier le stade dans Classic.',tip:'Le simulateur de capacité historique utilise les ratios 22 / 39 / 30 / 8 / 1 %. Les scénarios financiers utilisent vos montants : ils ne prévoient ni affluence ni rentabilité.',page:'stadium',action:'Comparer mes projets'},
  {id:'data',title:'Conserver ses données et gérer son accès',duration:'2 min',intro:'Gardez une copie de votre travail et sachez où retrouver les réglages de votre espace.',steps:[
    ['Importer un fichier au bon endroit','Dans Connexion & données, choisissez un ODS, CSV ou JSON (8 Mo maximum). Pour CSV/JSON, vérifiez le club et la destination Académie ou Effectif senior, puis cliquez sur « Importer et sauvegarder ». Le classeur Moeskroen.ods répartit ses feuilles connues automatiquement.'],
    ['Exporter et vérifier l’historique','Le bouton « Exporter » de « Conserver une copie complète » télécharge clubs, instantanés, notes, plannings et matchs, sans clés API. Les tableaux de joueurs proposent aussi « Exporter CSV ». L’historique distingue date observée et date d’import.'],
    ['Protéger son compte','Dans « Votre espace. Vos accès. », saisissez votre mot de passe actuel puis deux fois le nouveau (12 caractères minimum). Après validation, toutes vos sessions sont fermées : reconnectez-vous avec le nouveau mot de passe. Seul l’administrateur voit la création d’accès pour d’autres managers.']
  ],result:'Vous savez exporter votre travail, choisir une source et gérer votre mot de passe.',tip:'Le fichier d’export complet est une copie à conserver ; il ne se réimporte pas comme un simple fichier de joueurs. En cas de perte d’accès ou de restauration complète, contactez l’administrateur.',page:'settings',action:'Ouvrir les données et les accès'},
  {id:'vacation',title:'Préparer Classic et partir en vacances',duration:'3 min',intro:'Préparez une composition par défaut ou un match futur, puis choisissez si le relais doit seulement proposer des équipes ou les envoyer pendant une période précise.',steps:[
    ['Vérifier la cible et la connexion','Choisissez le bon club dans le sélecteur. Dans Mode vacances, contrôlez l’état de la connexion pour les écritures. Les clubs suivis ne peuvent pas recevoir de composition. Le paramètre développeur IV se renseigne dans Connexion & données.'],
    ['Préparer puis confirmer un envoi','Choisissez la composition par défaut ou un match du calendrier, puis un XV optimisé ou votre XV sauvegardé. Calculez l’aperçu, relisez les joueurs, les changements et les tactiques conservées. Le nombre de remplaçants suit le format renvoyé par Classic (7 ou 8). Si le format limite le banc à 7, la place locale 23 est écartée et signalée. Le dialogue de confirmation nomme le club et la cible ; sa validation modifie le jeu.'],
    ['Définir un relais daté','Dans Règles vacances, renseignez le début et la fin, l’objectif, le format et le seuil d’énergie, les exclusions et les responsables. Préparer uniquement conserve des propositions dans l’outil. Envoyer automatiquement autorise des envois pour les matchs éligibles selon ces règles. Les règles restent désactivées tant que vous ne les activez pas explicitement. Vérifiez que cet usage est autorisé par les règles de Classic.'],
    ['Suivre et arrêter','Consultez Journal & alertes dans cet espace : aucun courriel n’est envoyé. Le relais planifié vérifie les règles toutes les 15 minutes sur le serveur. Arrêter ce club et Tout arrêter empêchent les prochains envois ; une requête déjà transmise ne peut pas être annulée. Un résultat incertain demande un contrôle dans Classic avant toute reprise.']
  ],result:'Vous savez distinguer une préparation locale, un envoi confirmé et une règle automatique limitée dans le temps.',tip:'Un match sans échéance officielle fiable reste bloqué : enregistrez d’abord une composition pour ce match dans Classic, puis recalculez l’aperçu. Blessure ou énergie inconnue empêchent l’envoi. Continuez à vous connecter régulièrement au jeu.',page:'vacation',action:'Ouvrir Mode vacances'}
];

const faqs=[
  ['Dois-je choisir un mentor précis pour bien démarrer ?','Non. Choisissez librement un mentor disponible dans Classic. Le parcours reprend des conseils de Franck, pas une obligation du jeu ni une liste de managers imposés.'],
  ['Cocher « Pris en compte » réalise-t-il une action dans Classic ?','Non. La carte « Bien démarrer » conserve votre déclaration privée pour le club sélectionné. Elle ne recrute aucun joueur ou membre du staff, ne construit aucune tribune et ne vérifie pas automatiquement qu’une action a été faite. Vous pouvez rouvrir la carte et modifier vos cases.'],
  ['Les 300 000 unités sont-elles mon solde et mardi minuit ma prochaine échéance ?','Les 300 000 unités virtuelles sont la dotation de départ évoquée dans les conseils de Franck, pas votre solde observé. Vérifiez votre trésorerie dans Classic. Pour le repère économique du mardi à minuit, vérifiez la date et le fuseau du jeu avant de créer un rappel ; aucun rendez-vous n’est créé automatiquement.'],
  ['La répartition du stade écrase-t-elle mes données ou lance-t-elle des travaux ?','Saisir un total affiche seulement un aperçu. Le bouton « Remplacer les cinq capacités cibles » remplace ces cinq champs dans le brouillon ; les capacités actuelles, tarifs, trésorerie, réserve et notes sont conservés. Enregistrez ensuite le scénario. Les données manquantes restent inconnues et les travaux restent à décider dans Classic après lecture du devis réel.'],
  ['Quel identifiant utiliser pour me connecter ?','Celui de l’outil, choisi à l’inscription ou reçu sur invitation, avec son mot de passe associé. Le compte Classic sert ensuite à importer les données via sa clé manager. Si vous avez perdu l’accès à l’outil, contactez l’administrateur.'],
  ['La clé Classic est refusée : que vérifier ?','Copiez la ligne Access Key complète, sans oublier m= et &mk=. Utilisez la clé du bon manager, pas son mot de passe ni la clé développeur. Si la clé a changé dans Classic, utilisez Reconnecter mon compte. Pour un problème de clé développeur, contactez l’administrateur.'],
  ['La synchronisation échoue ou reste en cours','Attendez la fin de l’opération avant de relancer. Si le message indique un délai, patientez avant de réessayer. Les observations déjà conservées restent consultables. Vérifiez la clé et la disponibilité de Classic ; transmettez à l’administrateur le texte de l’erreur, jamais votre clé ou votre mot de passe.'],
  ['Mon club ou mes joueurs n’apparaissent pas','Vérifiez le club en haut à droite et retirez les filtres de recherche. Importez ou actualisez le compte Classic. Un club ajouté manuellement n’obtient pas automatiquement les droits de lecture privés. Une académie peut aussi être vide dans le jeu.'],
  ['Pourquoi ne vois-je pas encore de progression ?','L’historique compare des observations successives. Un premier import ne montre pas d’évolution ; un import identique n’ajoute pas un nouveau relevé. Actualisez après un changement réel dans Classic et vérifiez la date d’observation.'],
  ['Mon XV ou mon entraînement n’a pas changé dans Classic','Enregistrer le XV ou un planning dans Effectif & XV, Optimisation ou Entraînement conserve une préparation locale. Seule la rubrique Mode vacances peut envoyer une composition après confirmation, ou via une règle automatique activée. Les entraînements restent à configurer dans Classic.'],
  ['Pourquoi l’envoi de mon match est-il bloqué ?','L’envoi exige une échéance officielle fiable, une équipe complète et des données utilisables sur l’énergie et les blessures. Si le match n’a jamais eu de composition enregistrée, enregistrez-en une dans Classic puis recalculez. L’outil ne déduit pas l’échéance de l’heure du coup d’envoi.'],
  ['Pourquoi le banc comporte-t-il 7 ou 8 remplaçants ?','La préparation locale accepte les places 1 à 23. L’envoi suit le format effectivement renvoyé par Classic, avec 7 ou 8 remplaçants. Quand le format ne prévoit que 7 places sur le banc, le joueur de la place 23 est signalé dans l’aperçu et n’est pas transmis. Un format récent demande un premier envoi manuel vérifié avant les envois automatiques.'],
  ['Comment arrêter le mode vacances ?','Ouvrez Mode vacances puis Arrêter ce club ou Tout arrêter. Les règles sont désactivées pour les prochains passages. Une requête déjà transmise ne peut pas être annulée. Après un résultat incertain, ouvrez la proposition dans le journal et cliquez sur Vérifier le résultat dans Classic. Si la composition diffère, relisez le contrôle puis choisissez éventuellement de conserver l’état actuel. La suspension est levée sans renvoyer la composition ; les règles restent désactivées et nécessitent une nouvelle activation explicite.'],
  ['Le mode vacances fonctionne-t-il si je ferme le navigateur ?','Le relais s’exécute sur le serveur toutes les 15 minutes lorsque le service planifié est actif. Seules les règles enregistrées et explicitement activées sont traitées pendant leurs dates. Les résultats et alertes restent dans Journal & alertes ; aucun mail n’est envoyé.'],
  ['Pourquoi l’optimisation demande-t-elle l’échelle d’énergie ?','Classic fournit un pourcentage jusqu’à 110 pour un compte premium et un niveau de 1 à 11 sinon. Si les chiffres sont ambigus, le mode automatique suspend le filtre et le bonus d’énergie. Choisissez le format de votre source : le mode Niveau utilise une conversion indicative ×10. Une énergie inconnue reste inconnue.'],
  ['Pourquoi aucun programme ou aucun XV complet n’est-il proposé ?','Le moteur utilise uniquement les compétences dévoilées. Si les données de l’académie sont masquées, il ne peut pas inventer des priorités d’entraînement. Un effectif insuffisant, des blessures, un seuil d’énergie élevé ou des affinités inconnues peuvent laisser des postes vacants. Consultez les explications, actualisez vos données et ajustez vos critères.'],
  ['Que faire avant de quitter un écran ?','Enregistrez le planning, le XV, la note ou la date du calendrier et attendez la confirmation. Si ces saisies ont changé, la navigation, le changement de club ou la déconnexion demandent confirmation avant abandon. Le navigateur peut aussi avertir lors d’une fermeture ou d’un rechargement. Les brouillons restent dans l’écran ouvert, sans sauvegarde automatique : acceptez de quitter seulement si vous souhaitez les abandonner. Fermer simplement « Mode d’emploi » garde la saisie en cours.'],
  ['Que signifie « modifié dans une autre session » ?','Un autre onglet ou appareil a enregistré une version différente depuis votre lecture. Le planning, le XV, le calendrier ou la note ne l’écrase pas et conserve votre brouillon à l’écran. Relevez les éléments à garder, puis utilisez le bouton de relecture proposé : il remplace le brouillon après confirmation. Reprenez ensuite vos changements sur cette version. Il n’y a pas de fusion automatique.'],
  ['Pourquoi faut-il dater une séance issue du planning ?','Le planning décrit une intention. Choisir son créneau reprend seulement la saison, la semaine, le numéro et la compétence prévue. La date réelle reste vide et obligatoire ; elle n’est pas déduite du calendrier. Vérifiez la compétence effectivement travaillée. Une nouvelle déclaration pour le même créneau remplace la précédente, sans envoyer d’entraînement à Classic.'],
  ['Quel dénominateur utiliser pour la matrice des attaques ?','Chaque pourcentage utilise le nombre d’actions adverses classées de sa propre zone, affiché en fin de ligne. La couverture générale utilise tous les événements des matchs retenus, pour les deux équipes. Une zone sans observation ne donne aucun pourcentage et ne permet pas de conclure sur les habitudes de l’adversaire.'],
  ['Pourquoi le stade ou l’analyse ne donne-t-il pas une prédiction certaine ?','Les ratios du stade et les affinités de poste sont des modèles d’aide. L’analyse des commentaires ne reconnaît qu’une partie des événements. Les limites et les sources sont affichées pour éviter de confondre observations, estimations et règles officielles.']
];

const contextLessons:Record<string,string>={contact:'contact',home:'daily',profile:'profile',progression:'progression',season:'season',vacation:'vacation',academy:'academy-followup',squad:'squad',matches:'opponents',training:'training',optimization:'lineup-lab',stadium:'stadium',settings:'connect',guide:'start'};
const storageKey=(username:string)=>'brt-tutorial-v1:'+username;
function readProgress(username:string):string[]{try{const value=JSON.parse(localStorage.getItem(storageKey(username))||'[]');return Array.isArray(value)?[...new Set<string>(value.filter((id:unknown)=>typeof id==='string'&&lessons.some(l=>l.id===id)))]:[]}catch{return []}}
const normalize=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();

export function Tutorial({username,go,initialLesson='start',setup=false,inDialog=false}:{username:string;go:(page:string)=>void;initialLesson?:string;setup?:boolean;inDialog?:boolean}){
  const [selected,setSelected]=useState(lessons.find(l=>l.id===initialLesson)?.id||'start');
  const [completed,setCompleted]=useState(()=>readProgress(username));
  const [query,setQuery]=useState('');
  const [storageUnavailable,setStorageUnavailable]=useState(false);
  const lessonTitle=useId();
  const heading=useRef<HTMLHeadingElement>(null),shouldFocus=useRef(false);
  const index=lessons.findIndex(l=>l.id===selected),lesson=lessons[index];
  const matchingFaqs=faqs.map(pair=>pair.map(text=>tr(text))).filter(pair=>normalize(pair.join(' ')).includes(normalize(query)));
  const select=(id:string)=>{shouldFocus.current=true;setSelected(id)};
  useEffect(()=>{if(shouldFocus.current){heading.current?.focus({preventScroll:true});heading.current?.scrollIntoView({block:'nearest',behavior:'smooth'});shouldFocus.current=false}},[selected]);
  useEffect(()=>{
    const sync=()=>setCompleted(readProgress(username));
    const storageSync=(event:StorageEvent)=>{if(event.key===null||event.key===storageKey(username))sync()};
    window.addEventListener('brt-tutorial-progress',sync);
    window.addEventListener('storage',storageSync);
    return()=>{window.removeEventListener('brt-tutorial-progress',sync);window.removeEventListener('storage',storageSync)};
  },[username]);
  const mark=()=>{
    const toggle=(values:string[])=>values.includes(selected)?values.filter(id=>id!==selected):[...values,selected];
    try{const next=toggle(readProgress(username));localStorage.setItem(storageKey(username),JSON.stringify(next));setCompleted(next);setStorageUnavailable(false);window.dispatchEvent(new Event('brt-tutorial-progress'))}
    catch{setCompleted(toggle(completed));setStorageUnavailable(true)}
  };
  return <div className={'tutorial '+(inDialog?'tutorial-in-dialog':'')}>
    {!inDialog&&<section className="tutorial-hero"><div><span className="eyebrow">{tr("LE CARNET DE DÉMARRAGE")}</span><h2>{tr("Prenez vos marques.")}<br/><em>{tr("Le reste se joue sur le terrain.")}</em></h2><p>{lessons.length}{tr(" chapitres courts, à votre rythme. Lisez une étape, ouvrez l’écran correspondant, puis revenez ici quand vous en avez besoin.")}</p></div><div className="tutorial-hero-badge"><Compass size={42}/><strong>{lessons.reduce((total,lesson)=>total+parseInt(lesson.duration),0)}{tr(" min")}</strong><span>{tr("pour découvrir l’atelier")}</span></div></section>}
    <div className="tutorial-layout"><aside className="tutorial-index card"><div><span className="eyebrow">{tr("VOTRE PARCOURS")}</span><h2>{tr("Le guide, pas à pas")}</h2><p aria-live="polite">{completed.length} / {lessons.length}{tr(" chapitres marqués comme lus")}</p><progress max={lessons.length} value={completed.length} aria-label={tr("Progression du tutoriel")}/></div><nav aria-label={tr("Chapitres du tutoriel")}>{lessons.map((item,i)=><button key={item.id} className={selected===item.id?'selected':''} aria-current={selected===item.id?'step':undefined} onClick={()=>select(item.id)}><span className={completed.includes(item.id)?'lesson-number done':'lesson-number'}>{completed.includes(item.id)?<Check size={14}/>:String(i+1).padStart(2,'0')}</span><span>{tr(item.title)}<small>{item.duration}{completed.includes(item.id)?tr(" · Lu"):''}</small></span><ChevronRight size={15}/></button>)}</nav><small className="tutorial-storage">{tr("Progression propre à ")}{username}{tr(", sur ce navigateur.")}{storageUnavailable&&tr(" Le stockage est indisponible : elle sera conservée seulement tant que ce guide reste ouvert.")}</small></aside>
      <article className="tutorial-lesson card" aria-labelledby={lessonTitle}><div className="lesson-heading"><span className="eyebrow">{tr("CHAPITRE ")}{String(index+1).padStart(2,'0')} / {lessons.length} · {lesson.duration}</span><h2 id={lessonTitle} ref={heading} tabIndex={-1}>{tr(lesson.title)}</h2><p>{tr(lesson.intro)}</p></div><ol className="lesson-steps">{lesson.steps.map(([title,body],i)=><li key={tr(title)}><span>{i+1}</span><div><h3>{tr(title)}</h3><p>{tr(body)}</p></div></li>)}</ol><div className="lesson-result"><CheckCircle2 size={21}/><div><strong>{tr("À la fin de cette étape")}</strong><p>{tr(lesson.result)}</p></div></div><div className="lesson-tip"><Lightbulb size={20}/><p>{tr(lesson.tip)}</p></div><div className="lesson-actions"><button className={'button '+(completed.includes(selected)?'secondary':'primary')} aria-pressed={completed.includes(selected)} onClick={mark}><Check size={16}/>{completed.includes(selected)?tr("Lu — annuler ce repère"):tr("Marquer comme lu")}</button>{(!setup||lesson.page==='settings')&&<button className="text-button" onClick={()=>go(lesson.page)}>{setup?tr("Revenir au formulaire d’import"):tr(lesson.action)}<ArrowRight size={16}/></button>}</div>{inDialog&&!setup&&<p className="tutorial-save-hint">{tr("Pour garder une saisie en cours, fermez simplement l’aide. Enregistrez avant d’ouvrir une autre rubrique.")}</p>}<div className="lesson-pagination"><button className="text-button" disabled={index===0} onClick={()=>select(lessons[index-1].id)}><ArrowLeft size={16}/>{tr("Précédent")}</button><span>{index+1} / {lessons.length}</span><button className="text-button" disabled={index===lessons.length-1} onClick={()=>select(lessons[index+1].id)}>{tr("Suivant")}<ArrowRight size={16}/></button></div></article>
    </div>
    <section className="card tutorial-faq"><div className="tutorial-section-heading"><div><span className="eyebrow">{tr("UN COUP DE MAIN")}</span><h2>{tr("Les questions des premiers jours")}</h2></div><label className="search"><Search size={17}/><input aria-label={tr("Rechercher dans l’aide")} placeholder={tr("Clé, sauvegarde, joueurs…")} value={query} onChange={e=>setQuery(e.target.value)}/></label></div><div className="faq-list">{matchingFaqs.map(([question,answer])=><details key={question}><summary>{question}</summary><p>{answer}</p></details>)}{!matchingFaqs.length&&<p role="status">{tr("Aucune réponse pour cette recherche. Essayez « clé », « joueur » ou « enregistrer ».")}</p>}</div></section>
    <section className="card tutorial-reference"><span className="eyebrow">{tr("POUR ALLER PLUS LOIN")}</span><h2>{tr("Les mots et les chiffres de l’atelier")}</h2><div className="tutorial-reference-grid"><details><summary>{tr("Le petit lexique")}</summary><dl><dt>{tr("Instantané")}</dt><dd>{tr("État de vos joueurs conservé à une date d’observation.")}</dd><dt>{tr("Synchroniser")}</dt><dd>{tr("Relire les données disponibles dans l’API Classic. Cela ne change pas vos choix dans le jeu.")}</dd><dt>{tr("Clé manager")}</dt><dd>{tr("La ligne m=…&mk=… qui donne accès aux données de votre compte ; les envois passent par les validations de Mode vacances.")}</dd><dt>{tr("Compétences masquées")}</dt><dd>{tr("? = inconnue ; B = basse ; M = moyenne ; H = haute. Elles restent distinctes des valeurs numériques.")}</dd></dl></details><details><summary>{tr("Comprendre les estimations")}</summary><h3>{tr("Génération U20")}</h3><p>{tr("Projection personnelle de Franck : saison actuelle + 20 − âge, moins une saison si l’anniversaire est encore à venir. On conserve une saison paire et un anniversaire avant la semaine 8. Ce repère n’est pas une validation officielle d’éligibilité.")}</p><h3>{tr("Affinité de poste")}</h3><p>{tr("Moyenne pondérée des compétences dévoilées. Ailier = (3 × vitesse + 2 × agilité + attaque) / 6 ; pilier = (3 × force + 2 × technique + endurance) / 6. Un calcul nécessitant une compétence inconnue reste incomplet.")}</p><h3>{tr("Analyse et stade")}</h3><p>{tr("Les événements structurés utilisent field, possession et att. La classification des commentaires reste estimative. Le stade utilise les ratios 22 / 39 / 30 / 8 / 1 % du classeur, sans prévision financière.")}</p></details><details><summary>{tr("Une routine simple chaque semaine")}</summary><ol><li>{tr("Actualiser ses équipes et vérifier les dates d’observation.")}</li><li>{tr("Relire les joueurs suivis et leurs évolutions.")}</li><li>{tr("Préparer puis enregistrer le XV et le planning.")}</li><li>{tr("Appliquer ses choix dans Classic et analyser les rencontres utiles.")}</li><li>{tr("Exporter régulièrement une copie de son travail.")}</li></ol></details></div><p className="tutorial-privacy"><ShieldCheck size={17}/>{tr("Vos repères de lecture ne modifient aucune donnée de vos équipes. Continuez à visiter Classic régulièrement : utiliser cet atelier ne remplace pas votre activité dans le jeu.")}</p></section>
  </div>;
}

export function TutorialWelcome({onOpen,compact=false}:{onOpen:()=>void;compact?:boolean}){return <section className={'tutorial-welcome '+(compact?'compact':'')}><span className="tutorial-welcome-icon"><BookOpen size={24}/></span><div><span className="eyebrow">{tr("PREMIERS PAS")}</span><h2>{compact?tr("Besoin d’aide pour commencer ?"):tr("Nouveau dans l’atelier ?")}</h2><p>{tr("Un parcours guidé pour connecter Classic, comprendre vos données et préparer votre équipe.")}</p></div><button className="button secondary" onClick={onOpen}>{tr("Commencer le tutoriel")}<ArrowRight size={16}/></button></section>}

export function HelpButton({onClick}:{onClick:()=>void}){return <button className="button secondary help-button" aria-label={tr("Mode d’emploi")} onClick={onClick}><HelpCircle size={17}/><span>{tr("Mode d’emploi")}</span></button>}

export function TutorialDialog({username,page,onClose,go,setup=false}:{username:string;page:string;onClose:()=>void;go:(page:string)=>void;setup?:boolean}){
  const dialog=useRef<HTMLDialogElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const node=dialog.current;node?.showModal();return()=>{node?.close();previous?.focus()}},[]);
  return <dialog className="tutorial-dialog" ref={dialog} aria-labelledby="tutorial-dialog-title" onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===e.currentTarget)onClose()}}><header><div><BookOpen size={20}/><h2 id="tutorial-dialog-title">{tr("Mode d’emploi de l’atelier")}</h2></div><button autoFocus className="icon-button" aria-label={tr("Fermer le tutoriel")} onClick={onClose}><X size={22}/></button></header><Tutorial key={username} username={username} initialLesson={setup?'connect':contextLessons[page]||'start'} setup={setup} inDialog go={next=>{onClose();go(next)}}/></dialog>;
}
